const config = {
  "previewFeatures": [
    "views"
  ],
  "clientVersion": "7.3.0",
  "engineVersion": "9d6ad21cbbceab97458517b147a6a09ff43aa735",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider        = \"prisma-client-js\"\n  output          = \"../src/generated/prisma\"\n  previewFeatures = [\"views\"]\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================================================\n// WEB 알림마당 > 공지사항, 게시판, 갤러리, 식단표, 프로그램 일정표\n// ADMIN 콘텐츠 관리 > 공지사항 관리, 게시판 관리, 갤러리 관리, 식단표 관리, 프로그램 관리\n// ============================================================================\n\n// 공지사항\nmodel Notice {\n  /// 공지 ID (Primary Key)\n  id          BigInt       @id @default(autoincrement())\n  /// 공지 제목\n  title       String\n  /// 공지 내용 (HTML)\n  content     String\n  /// 카테고리 (GENERAL, URGENT, EVENT, EDUCATION, MAINTENANCE 등)\n  category    String?      @default(\"GENERAL\")\n  /// 상단 고정 여부\n  isPinned    Boolean      @default(false) @map(\"is_pinned\")\n  /// 활성화 여부\n  isActive    Boolean      @default(true) @map(\"is_active\")\n  /// 조회수\n  viewCount   Int          @default(0) @map(\"view_count\")\n  /// 게시일시\n  publishedAt DateTime?    @map(\"published_at\") @db.Timestamptz(6)\n  /// 작성자 ID (외래키)\n  createdBy   BigInt?      @map(\"created_by\")\n  /// 생성일시\n  createdAt   DateTime     @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime     @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  files       NoticeFile[]\n  creator     Employee?    @relation(\"NoticeCreator\", fields: [createdBy], references: [id], onUpdate: NoAction)\n\n  @@index([isActive, publishedAt(sort: Desc)], map: \"idx_notices_active\")\n  @@index([isPinned(sort: Desc), createdAt(sort: Desc)], map: \"idx_notices_pinned\")\n  @@map(\"notices\")\n}\n\n// 공지사항 - 첨부 파일\nmodel NoticeFile {\n  /// 연결 ID (Primary Key)\n  id        BigInt      @id @default(autoincrement())\n  /// 공지 ID\n  noticeId  BigInt      @map(\"notice_id\")\n  /// 파일 ID\n  fileId    BigInt      @map(\"file_id\")\n  /// 생성일시\n  createdAt DateTime    @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  file      FileStorage @relation(\"NoticeFiles\", fields: [fileId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  notice    Notice      @relation(fields: [noticeId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"notice_files\")\n}\n\n// 게시판 - 게시글\nmodel BoardPost {\n  /// 게시글 ID (Primary Key)\n  id        BigInt         @id @default(autoincrement())\n  /// 게시판 구분 키\n  boardKey  String         @map(\"board_key\")\n  /// 게시글 제목\n  title     String\n  /// 게시글 내용\n  content   String\n  /// 작성자 ID\n  authorId  BigInt?        @map(\"author_id\")\n  /// 조회수\n  viewCount Int            @default(0) @map(\"view_count\")\n  /// 상단 고정 여부 (공지형 게시글 등)\n  isPinned  Boolean        @default(false) @map(\"is_pinned\")\n  /// 댓글 잠금 여부 (댓글 작성 불가 처리)\n  isLocked  Boolean        @default(false) @map(\"is_locked\")\n  /// 생성일시\n  createdAt DateTime       @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt DateTime       @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  comments  BoardComment[]\n  files     BoardFile[]\n  author    Employee?      @relation(fields: [authorId], references: [id], onUpdate: NoAction)\n\n  @@index([authorId], map: \"idx_board_posts_author\")\n  @@index([boardKey, createdAt(sort: Desc)], map: \"idx_board_posts_board_created\")\n  @@index([isPinned(sort: Desc), createdAt(sort: Desc)], map: \"idx_board_posts_pinned\")\n  @@map(\"board_posts\")\n}\n\n// 게시판 - 첨부 파일\nmodel BoardFile {\n  /// 연결 ID\n  id        BigInt      @id @default(autoincrement())\n  /// 게시글 ID\n  postId    BigInt      @map(\"post_id\")\n  /// 파일 ID\n  fileId    BigInt      @map(\"file_id\")\n  /// 생성일시\n  createdAt DateTime    @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  file      FileStorage @relation(\"BoardFiles\", fields: [fileId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  post      BoardPost   @relation(fields: [postId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"board_files\")\n}\n\n// 게시판 - 댓글\nmodel BoardComment {\n  /// 댓글 ID\n  id            BigInt         @id @default(autoincrement())\n  /// 게시글 ID\n  postId        BigInt         @map(\"post_id\")\n  /// 부모 댓글 ID (대댓글인 경우, 외래키)\n  parentId      BigInt?        @map(\"parent_id\")\n  /// 작성자 ID\n  authorId      BigInt?        @map(\"author_id\")\n  /// 댓글 내용\n  content       String\n  /// 삭제 여부\n  isDeleted     Boolean        @default(false) @map(\"is_deleted\")\n  /// 비회원 닉네임\n  guestNickname String?        @map(\"guest_nickname\")\n  /// 비회원 비밀번호\n  guestPassword String?        @map(\"guest_password\")\n  /// 생성일시\n  createdAt     DateTime       @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt     DateTime       @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  author        Employee?      @relation(fields: [authorId], references: [id], onUpdate: NoAction)\n  parent        BoardComment?  @relation(\"BoardCommentParent\", fields: [parentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  replies       BoardComment[] @relation(\"BoardCommentParent\")\n  post          BoardPost      @relation(fields: [postId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"board_comments\")\n}\n\n// 갤러리 - 항목 (사진첩)\nmodel GalleryItem {\n  /// 갤러리 항목 ID (Primary Key)\n  id          BigInt        @id @default(autoincrement())\n  /// 제목\n  title       String?\n  /// 설명\n  description String?\n  /// 카테고리 (행사, 일상 등)\n  category    String?       @default(\"GENERAL\")\n  /// 행사 일자\n  eventDate   DateTime?     @map(\"event_date\") @db.Date\n  /// 작성자 ID (외래키)\n  createdBy   BigInt?       @map(\"created_by\")\n  /// 공개 여부\n  isPublic    Boolean       @default(true) @map(\"is_public\")\n  /// 생성일시\n  createdAt   DateTime      @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime      @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  files       GalleryFile[]\n  creator     Employee?     @relation(fields: [createdBy], references: [id], onUpdate: NoAction)\n\n  @@index([eventDate(sort: Desc)], map: \"idx_gallery_items_date\")\n  @@index([isPublic], map: \"idx_gallery_items_public\")\n  @@map(\"gallery_items\")\n}\n\n// 갤러리 - 파일\nmodel GalleryFile {\n  /// 연결 ID (Primary Key)\n  id        BigInt      @id @default(autoincrement())\n  /// 갤러리 ID\n  galleryId BigInt      @map(\"gallery_id\")\n  /// 파일 ID\n  fileId    BigInt      @map(\"file_id\")\n  /// 정렬 순서\n  sortOrder Int         @default(0) @map(\"sort_order\")\n  /// 생성일시\n  createdAt DateTime    @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  file      FileStorage @relation(\"GalleryFiles\", fields: [fileId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  gallery   GalleryItem @relation(fields: [galleryId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"gallery_files\")\n}\n\n// 식단표\nmodel MealPlan {\n  /// 식단표 ID\n  id               BigInt         @id @default(autoincrement())\n  /// 시설 코드\n  facilityCode     String         @default(\"DEFAULT\") @map(\"facility_code\")\n  week_start_date  DateTime       @db.Date\n  /// 식단 대상 월 (YYYYMM)\n  mealMonth        Int            @default(202601) @map(\"meal_month\")\n  /// 작성자 ID\n  createdBy        BigInt?        @map(\"created_by\")\n  /// 영양 관리자\n  nutritionManager String?        @map(\"nutrition_manager\")\n  /// 상태 (DRAFT, PUBLISHED 등)\n  status           String         @default(\"DRAFT\")\n  /// 비고/특이사항\n  notes            String?\n  /// 생성일시\n  createdAt        DateTime       @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt        DateTime       @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  mealPlanItems    MealPlanItem[] @relation(\"MealPlanItems\")\n  creator          Employee?      @relation(fields: [createdBy], references: [id], onUpdate: NoAction)\n\n  @@unique([facilityCode, week_start_date], map: \"meal_plans_uniq_week\")\n  @@map(\"meal_plans\")\n}\n\n/// 식단 상세 항목 (정규화된 데이터)\nmodel MealPlanItem {\n  /// 항목 ID (Primary Key)\n  id         BigInt   @id @default(autoincrement())\n  /// 식단표 ID (외래키)\n  mealPlanId BigInt   @map(\"meal_plan_id\")\n  /// 식사 날짜\n  mealDate   DateTime @map(\"meal_date\") @db.Date\n  /// 식사 유형 (BREAKFAST, LUNCH, DINNER, SNACK)\n  mealType   String   @map(\"meal_type\")\n  /// 주 메뉴\n  mainMenu   String?  @map(\"main_menu\")\n  /// 부 메뉴\n  sideMenu   String?  @map(\"side_menu\")\n  /// 국/찌개\n  soup       String?\n  /// 디저트/김치\n  dessert    String?\n  calories   Int?     @map(\"calories\")\n  /// 생성일시\n  createdAt  DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt  DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  mealPlan   MealPlan @relation(\"MealPlanItems\", fields: [mealPlanId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"meal_plan_items\")\n}\n\n/// 프로그램\nmodel Program {\n  /// 프로그램 ID (Primary Key)\n  id          BigInt            @id @default(autoincrement())\n  /// 프로그램명\n  title       String\n  /// 프로그램 설명\n  description String?\n  /// 카테고리\n  category    String?\n  /// 활성화 여부\n  isActive    Boolean           @default(true) @map(\"is_active\")\n  /// 생성자 ID\n  createdBy   BigInt?           @map(\"created_by\")\n  /// 추가 메타데이터 (JSON)\n  meta        Json              @default(\"{}\")\n  /// 생성일시\n  createdAt   DateTime          @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime          @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  schedules   ProgramSchedule[]\n  creator     Employee?         @relation(fields: [createdBy], references: [id], onUpdate: NoAction)\n\n  @@index([isActive], map: \"idx_programs_active\")\n  @@index([category], map: \"idx_programs_category\")\n  @@map(\"programs\")\n}\n\n/// 프로그램 일정\nmodel ProgramSchedule {\n  /// 일정 ID (Primary Key)\n  id         BigInt              @id @default(autoincrement())\n  /// 프로그램 ID (외래키)\n  programId  BigInt              @map(\"program_id\")\n  /// 시작일시\n  startsAt   DateTime            @map(\"starts_at\") @db.Timestamptz(6)\n  /// 종료일시\n  endsAt     DateTime            @map(\"ends_at\") @db.Timestamptz(6)\n  /// 장소\n  location   String?\n  /// 정원\n  capacity   Int?\n  /// 상태 (PLANNED, ONGOING, COMPLETED, CANCELLED)\n  status     String              @default(\"PLANNED\")\n  /// 생성일시\n  createdAt  DateTime            @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt  DateTime            @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  attendance ProgramAttendance[]\n  program    Program             @relation(fields: [programId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([programId, startsAt], map: \"idx_program_schedules_program_time\")\n  @@map(\"program_schedules\")\n}\n\n// ============================================================================\n// WEB 알림마당 Views\n// ============================================================================\n\n/// Web 공지사항 목록 조회 뷰\nview WebNotice {\n  id          BigInt    @unique\n  title       String\n  content     String\n  category    String?\n  isPinned    Boolean   @map(\"is_pinned\")\n  isActive    Boolean   @map(\"is_active\")\n  viewCount   Int       @map(\"view_count\")\n  publishedAt DateTime? @map(\"published_at\") @db.Timestamptz(6)\n  createdAt   DateTime  @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt   DateTime  @map(\"updated_at\") @db.Timestamptz(6)\n  creatorName String?   @map(\"creator_name\")\n  creatorId   BigInt?   @map(\"creator_id\")\n  fileCount   Int       @map(\"file_count\")\n  files       Json\n\n  @@map(\"v_web_notices\")\n}\n\n/// Web 공지사항 상세 조회 뷰\nview WebNoticeDetail {\n  id          BigInt    @unique\n  title       String\n  content     String\n  category    String?\n  isPinned    Boolean   @map(\"is_pinned\")\n  viewCount   Int       @map(\"view_count\")\n  publishedAt DateTime? @map(\"published_at\") @db.Timestamptz(6)\n  createdAt   DateTime  @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt   DateTime  @map(\"updated_at\") @db.Timestamptz(6)\n  creatorName String?   @map(\"creator_name\")\n  creatorId   BigInt?   @map(\"creator_id\")\n  files       Json\n  prevNotice  Json?     @map(\"prev_notice\")\n  nextNotice  Json?     @map(\"next_notice\")\n\n  @@map(\"v_web_notice_detail\")\n}\n\n/// Web 게시판 목록 조회 뷰\nview WebBoardPost {\n  id           BigInt   @unique\n  boardKey     String   @map(\"board_key\")\n  title        String\n  content      String\n  viewCount    Int      @map(\"view_count\")\n  isPinned     Boolean  @map(\"is_pinned\")\n  isLocked     Boolean  @map(\"is_locked\")\n  createdAt    DateTime @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt    DateTime @map(\"updated_at\") @db.Timestamptz(6)\n  authorName   String?  @map(\"author_name\")\n  authorId     BigInt?  @map(\"author_id\")\n  commentCount Int      @map(\"comment_count\")\n  fileCount    Int      @map(\"file_count\")\n  files        Json\n\n  @@map(\"v_web_board_posts\")\n}\n\n/// Web 게시글 상세 조회 뷰\nview WebBoardPostDetail {\n  id           BigInt   @unique\n  boardKey     String   @map(\"board_key\")\n  title        String\n  content      String\n  viewCount    Int      @map(\"view_count\")\n  isPinned     Boolean  @map(\"is_pinned\")\n  isLocked     Boolean  @map(\"is_locked\")\n  createdAt    DateTime @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt    DateTime @map(\"updated_at\") @db.Timestamptz(6)\n  authorName   String?  @map(\"author_name\")\n  authorId     BigInt?  @map(\"author_id\")\n  files        Json\n  comments     Json\n  commentCount Int      @map(\"comment_count\")\n  prevPost     Json?    @map(\"prev_post\")\n  nextPost     Json?    @map(\"next_post\")\n\n  @@map(\"v_web_board_post_detail\")\n}\n\n/// Web 갤러리 목록 조회 뷰\nview WebGalleryItem {\n  id          BigInt    @unique\n  title       String?\n  description String?\n  category    String?\n  eventDate   DateTime? @map(\"event_date\") @db.Date\n  isPublic    Boolean   @map(\"is_public\")\n  createdAt   DateTime  @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt   DateTime  @map(\"updated_at\") @db.Timestamptz(6)\n  creatorName String?   @map(\"creator_name\")\n  creatorId   BigInt?   @map(\"creator_id\")\n  fileCount   Int       @map(\"file_count\")\n  thumbnail   Json?\n  files       Json\n\n  @@map(\"v_web_gallery_items\")\n}\n\n/// Web 식단표 목록 조회 뷰\nview WebMealPlan {\n  id               BigInt   @unique\n  facilityCode     String   @map(\"facility_code\")\n  weekStartDate    DateTime @map(\"week_start_date\") @db.Date\n  status           String\n  nutritionManager String?  @map(\"nutrition_manager\")\n  notes            String?\n  createdAt        DateTime @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt        DateTime @map(\"updated_at\") @db.Timestamptz(6)\n  creatorName      String?  @map(\"creator_name\")\n  creatorId        BigInt?  @map(\"creator_id\")\n  weekMeals        Json     @map(\"week_meals\")\n\n  @@map(\"v_web_meal_plans\")\n}\n\n/// 최신 콘텐츠 통합 조회 뷰\nview WebLatestContent {\n  id           BigInt   @unique\n  contentType  String   @map(\"content_type\")\n  title        String\n  summary      String?\n  createdAt    DateTime @map(\"created_at\") @db.Timestamptz(6)\n  viewCount    Int      @map(\"view_count\")\n  commentCount Int?     @map(\"comment_count\")\n  fileCount    Int      @map(\"file_count\")\n  authorName   String?  @map(\"author_name\")\n\n  @@map(\"v_web_latest_contents\")\n}\n\n// ============================================================================\n// WEB 이용안내 > 면회문의, 상담문의\n// ADMIN 콘텐츠 관리 > 문의 관리\n// ============================================================================\n\n/// 면회문의\nmodel VisitReservation {\n  /// 예약 ID (Primary Key)\n  id                    BigInt   @id @default(autoincrement())\n  /// 방문자 성함\n  visitorName           String   @map(\"visitor_name\")\n  /// 방문자 연락처\n  visitorPhone          String   @map(\"visitor_phone\")\n  /// 어르신과의 관계\n  visitorRelationship   String   @map(\"visitor_relationship\")\n  /// 어르신 성함\n  residentName          String   @map(\"resident_name\")\n  /// 방문 희망일\n  visitDate             DateTime @map(\"visit_date\") @db.Date\n  /// 방문 희망시간\n  visitTime             String   @map(\"visit_time\")\n  /// 방문 인원\n  visitorCount          Int      @default(1) @map(\"visitor_count\")\n  /// 방문 목적\n  visitPurpose          String?  @map(\"visit_purpose\")\n  /// 감염 증상 여부 (발열, 기침 등)\n  healthCheckSymptoms   Boolean  @default(false) @map(\"health_check_symptoms\")\n  /// 이동 보조 필요 여부\n  healthCheckAssistance Boolean  @default(false) @map(\"health_check_assistance\")\n  /// 추가 요청사항\n  notes                 String?\n  /// 개인정보 수집 동의 여부\n  isConsented           Boolean  @default(false) @map(\"is_consented\")\n  /// 처리 상태 (PENDING, APPROVED, REJECTED, CANCELLED)\n  status                String   @default(\"PENDING\")\n  /// 신청 IP 주소\n  ipAddress             String?  @map(\"ip_address\")\n  /// 사용자 브라우저 정보\n  userAgent             String?  @map(\"user_agent\")\n  /// 신청 시각\n  createdAt             DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정 시각\n  updatedAt             DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"visit_reservations\")\n}\n\n/// 상담문의\nmodel WebInquiry {\n  /// 문의 ID (Primary Key)\n  id            BigInt    @id @default(autoincrement())\n  /// 상담자 이름\n  name          String\n  /// 상담자 연락처\n  phone         String\n  /// 이메일\n  email         String?\n  /// 문의 유형\n  /// 입소 상담, 비용 상담, 방문 상담, 기타\n  type          String\n  /// 어르신 연령\n  residentAge   String?   @map(\"resident_age\")\n  /// 장기요양등급\n  careGrade     String?   @map(\"care_grade\")\n  /// 방문 상담 희망일\n  preferredDate DateTime? @map(\"preferred_date\") @db.Date\n  /// 상세 문의사항\n  message       String?\n  /// 개인정보 수집 동의 여부\n  isConsented   Boolean   @default(false) @map(\"is_consented\")\n  /// 처리 상태\n  /// PENDING: 접수, IN_PROGRESS: 상담중, DONE: 완료, CANCELLED: 취소\n  status        String    @default(\"PENDING\")\n  /// 문의 접수 IP 주소\n  ipAddress     String?   @map(\"ip_address\")\n  /// 사용자 브라우저 정보\n  userAgent     String?   @map(\"user_agent\")\n  /// 문의 생성 시각\n  createdAt     DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정 시각\n  updatedAt     DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"web_inquiries\")\n}\n\n// ============================================================================\n// ADMIN 콘텐츠 관리 > 팝업 관리\n// ============================================================================\n\n/// 팝업 배너\nmodel PopupBanner {\n  /// 배너 ID (Primary Key)\n  id          BigInt    @id @default(autoincrement())\n  /// 배너 제목\n  title       String\n  /// 배너 내용\n  content     String?\n  /// 이미지 URL\n  imageUrl    String?   @map(\"image_url\")\n  /// 링크 URL\n  linkUrl     String?   @map(\"link_url\")\n  /// 표시 유형 (POPUP, MODAL, BANNER 등)\n  displayType String    @default(\"POPUP\") @map(\"display_type\")\n  /// 위치 (TOP, CENTER, BOTTOM 등)\n  position    String?\n  /// 너비 (px)\n  width       Int?\n  /// 높이 (px)\n  height      Int?\n  /// 시작일\n  startDate   DateTime  @map(\"start_date\") @db.Date\n  /// 종료일\n  endDate     DateTime  @map(\"end_date\") @db.Date\n  /// 활성화 여부\n  isActive    Boolean   @default(true) @map(\"is_active\")\n  /// 하루 동안 보지 않기 옵션\n  showOnce    Boolean   @default(false) @map(\"show_once\")\n  /// 우선순위 (높을수록 먼저 표시)\n  priority    Int       @default(0)\n  /// 작성자 ID (외래키)\n  createdBy   BigInt?   @map(\"created_by\")\n  /// 생성일시\n  createdAt   DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  creator     Employee? @relation(fields: [createdBy], references: [id], onUpdate: NoAction)\n\n  @@index([isActive, startDate, endDate], map: \"idx_popup_banners_active_dates\")\n  @@index([priority(sort: Desc)], map: \"idx_popup_banners_priority\")\n  @@map(\"popup_banners\")\n}\n\n// ============================================================================\n// ADMIN 시스템 설정 > 권한 관리, 시설 정보 관리, 사이트 설정\n// ============================================================================\n\n/// 부서 정보\nmodel Department {\n  /// 부서 ID (Primary Key)\n  id          BigInt     @id @default(autoincrement())\n  /// 부서 코드 (고유값)\n  code        String     @unique\n  /// 부서명\n  name        String\n  /// 부서 설명\n  description String?\n  /// 활성화 여부\n  isActive    Boolean    @default(true) @map(\"is_active\")\n  /// 생성일시\n  createdAt   DateTime   @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime   @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  employees   Employee[]\n\n  @@map(\"departments\")\n}\n\n/// 직원 역할/권한 정보\nmodel EmployeeRole {\n  /// 역할 ID (Primary Key)\n  id          BigInt     @id @default(autoincrement())\n  /// 역할 코드 (고유값)\n  code        String     @unique\n  /// 역할명\n  name        String\n  /// 역할 설명\n  description String?\n  /// 권한 설정 (JSON)\n  permissions Json       @default(\"{}\")\n  /// 생성일시\n  createdAt   DateTime   @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime   @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  employees   Employee[]\n\n  @@map(\"employee_roles\")\n}\n\n/// 직원 정보\nmodel Employee {\n  /// 직원 ID (Primary Key)\n  id                           BigInt                  @id @default(autoincrement())\n  /// 부서 ID (외래키)\n  departmentId                 BigInt?                 @map(\"department_id\")\n  /// 역할 ID (외래키)\n  roleId                       BigInt?                 @map(\"role_id\")\n  /// 이메일 (로그인 ID, 고유값, 대소문자 구분 안함)\n  email                        String?                 @unique @db.Citext\n  /// 비밀번호 해시\n  passwordHash                 String?                 @map(\"password_hash\")\n  /// 직원명\n  name                         String\n  /// 전화번호\n  phoneNumber                  String?                 @map(\"phone_number\")\n  /// 입사일\n  hireDate                     DateTime?               @map(\"hire_date\") @db.Date\n  /// 퇴사일\n  resignDate                   DateTime?               @map(\"resign_date\") @db.Date\n  /// 재직 상태 (ACTIVE, RESIGNED 등)\n  status                       String                  @default(\"ACTIVE\")\n  /// 관리자 여부\n  isAdmin                      Boolean                 @default(false) @map(\"is_admin\")\n  /// 추가 메타데이터 (JSON)\n  meta                         Json                    @default(\"{}\")\n  /// 마지막 로그인 일시\n  lastLoginAt                  DateTime?               @map(\"last_login_at\") @db.Timestamptz(6)\n  /// 생성일시\n  createdAt                    DateTime                @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt                    DateTime                @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  attendanceRecords            AttendanceRecord[]\n  auditLogsAsActor             AuditLog[]              @relation(\"AuditActor\")\n  boardCommentsAuthored        BoardComment[]\n  boardPostsAuthored           BoardPost[]\n  carePlansCreated             CarePlan[]              @relation(\"CarePlanCreator\")\n  careTasksAssigned            CareTask[]              @relation(\"CareTaskAssignee\")\n  cctvViewLogsApproved         CctvViewLog[]           @relation(\"CctvApprover\")\n  cctvViewLogsAsViewer         CctvViewLog[]           @relation(\"CctvViewer\")\n  consultationsCounseled       ConsultationRecord[]    @relation(\"ConsultationCounselor\")\n  educations                   EmployeeEducation[]\n  department                   Department?             @relation(fields: [departmentId], references: [id], onUpdate: NoAction)\n  role                         EmployeeRole?           @relation(fields: [roleId], references: [id], onUpdate: NoAction)\n  inspectionsPerformed         FacilityInspection[]    @relation(\"InspectionInspector\")\n  filesCreated                 FileStorage[]           @relation(\"FileCreator\")\n  galleryItemsCreated          GalleryItem[]\n  grievancesAssigned           Grievance[]             @relation(\"GrievanceAssignee\")\n  incidentsReported            Incident[]              @relation(\"IncidentReporter\")\n  insuranceClaimHistoryChanged InsuranceClaimHistory[]\n  insuranceClaimsCreated       InsuranceClaim[]\n  inventoryTransactionsCreated InventoryTransaction[]\n  leaveApprovalsGiven          LeaveApproval[]\n  leaveRequests                LeaveRequest[]\n  mealPlansCreated             MealPlan[]\n  noticesCreated               Notice[]                @relation(\"NoticeCreator\")\n  payrollRecords               PayrollRecord[]\n  popupBannersCreated          PopupBanner[]\n  programAttendance            ProgramAttendance[]\n  programsCreated              Program[]\n  healthNotesRecorded          ResidentHealthNote[]    @relation(\"HealthNoteRecorder\")\n  vitalsRecorded               ResidentVital[]         @relation(\"VitalRecorder\")\n  shiftAssignments             ShiftAssignment[]\n  smsLogsSent                  SmsSendLog[]\n  transactionsCreated          Transaction[]\n  transportRequestsCreated     TransportRequest[]      @relation(\"TransportCreator\")\n  transportRequestsAsDriver    TransportRequest[]      @relation(\"TransportDriver\")\n  websiteSettingsUpdated       WebsiteSetting[]        @relation(\"SettingUpdater\")\n\n  @@index([departmentId], map: \"idx_employees_department\")\n  @@index([email], map: \"idx_employees_email\")\n  @@index([roleId], map: \"idx_employees_role\")\n  @@index([status], map: \"idx_employees_status\")\n  @@map(\"employees\")\n}\n\n/// 직원 교육 이력\nmodel EmployeeEducation {\n  /// 교육 이력 ID (Primary Key)\n  id               BigInt   @id @default(autoincrement())\n  /// 직원 ID (외래키)\n  employeeId       BigInt   @map(\"employee_id\")\n  /// 교육 일자\n  educationDate    DateTime @map(\"education_date\") @db.Date\n  /// 교육명\n  title            String\n  /// 교육 카테고리\n  category         String?\n  /// 교육 시간 (시간)\n  durationHours    Decimal? @map(\"duration_hours\") @db.Decimal(4, 1)\n  /// 강사명\n  instructor       String?\n  /// 이수 상태\n  completionStatus String   @default(\"COMPLETED\") @map(\"completion_status\")\n  /// 비고\n  notes            String?\n  /// 생성일시\n  createdAt        DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt        DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  employee         Employee @relation(fields: [employeeId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([employeeId, educationDate(sort: Desc)], map: \"idx_employee_educations_employee\")\n  @@map(\"employee_educations\")\n}\n\n/// 입소자 정보\nmodel Resident {\n  /// 입소자 ID (Primary Key)\n  id                BigInt               @id @default(autoincrement())\n  /// 입소자 코드 (고유값)\n  code              String               @unique\n  /// 입소자명\n  name              String\n  /// 생년월일\n  birthday          DateTime?            @db.Date\n  /// 성별\n  gender            String?\n  /// 주민등록번호 해시\n  nationalIdHash    String?              @map(\"national_id_hash\")\n  /// 입소일\n  admissionDate     DateTime?            @map(\"admission_date\") @db.Date\n  /// 퇴소일\n  dischargeDate     DateTime?            @map(\"discharge_date\") @db.Date\n  /// 입소 상태 (ADMITTED, DISCHARGED 등)\n  status            String               @default(\"ADMITTED\")\n  /// 보호자명\n  guardianName      String?              @map(\"guardian_name\")\n  /// 보호자 연락처\n  guardianPhone     String?              @map(\"guardian_phone\")\n  /// 메모\n  memo              String?\n  /// 추가 메타데이터 (JSON)\n  meta              Json                 @default(\"{}\")\n  /// 생성일시\n  createdAt         DateTime             @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt         DateTime             @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  carePlans         CarePlan[]\n  careTasks         CareTask[]\n  consultations     ConsultationRecord[]\n  dailyCareRecords  DailyCareRecord[]\n  grievances        Grievance[]\n  incidents         Incident[]\n  insuranceClaims   InsuranceClaim[]\n  invoices          InvoiceHeader[]\n  programAttendance ProgramAttendance[]\n  contacts          ResidentContact[]\n  healthNotes       ResidentHealthNote[]\n  medications       ResidentMedication[]\n  rooms             ResidentRoom[]\n  vitals            ResidentVital[]\n  transportRequests TransportRequest[]\n\n  @@index([admissionDate(sort: Desc)], map: \"idx_residents_admission\")\n  @@index([name], map: \"idx_residents_name\")\n  @@index([status], map: \"idx_residents_status\")\n  @@map(\"residents\")\n}\n\n/// 입소자 방/침대 배정 이력\nmodel ResidentRoom {\n  /// 배정 ID (Primary Key)\n  id         BigInt    @id @default(autoincrement())\n  /// 입소자 ID (외래키)\n  residentId BigInt    @map(\"resident_id\")\n  /// 방 번호/라벨\n  roomLabel  String    @map(\"room_label\")\n  /// 침대 번호/라벨\n  bedLabel   String?   @map(\"bed_label\")\n  /// 배정 시작일\n  startsAt   DateTime  @map(\"starts_at\") @db.Date\n  /// 배정 종료일\n  endsAt     DateTime? @map(\"ends_at\") @db.Date\n  /// 주 배정 여부\n  isPrimary  Boolean   @default(true) @map(\"is_primary\")\n  /// 생성일시\n  createdAt  DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt  DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  resident   Resident  @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([residentId, startsAt], map: \"idx_resident_rooms_resident\")\n  @@map(\"resident_rooms\")\n}\n\n/// 입소자 연락처 (보호자 등)\nmodel ResidentContact {\n  /// 연락처 ID (Primary Key)\n  id           BigInt   @id @default(autoincrement())\n  /// 입소자 ID (외래키)\n  residentId   BigInt   @map(\"resident_id\")\n  /// 연락처 이름\n  name         String\n  /// 관계 (자녀, 배우자 등)\n  relationship String?\n  /// 전화번호\n  phoneNumber  String?  @map(\"phone_number\")\n  /// 주 연락처 여부\n  isPrimary    Boolean  @default(false) @map(\"is_primary\")\n  /// 생성일시\n  createdAt    DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt    DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  resident     Resident @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"resident_contacts\")\n}\n\n/// 입소자 건강 노트\nmodel ResidentHealthNote {\n  /// 노트 ID (Primary Key)\n  id         BigInt    @id @default(autoincrement())\n  /// 입소자 ID (외래키)\n  residentId BigInt    @map(\"resident_id\")\n  /// 기록자 ID (외래키)\n  recordedBy BigInt?   @map(\"recorded_by\")\n  /// 노트 유형 (GENERAL, EMERGENCY 등)\n  noteType   String    @default(\"GENERAL\") @map(\"note_type\")\n  /// 내용\n  content    String\n  /// 생성일시\n  createdAt  DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  recorder   Employee? @relation(\"HealthNoteRecorder\", fields: [recordedBy], references: [id], onUpdate: NoAction)\n  resident   Resident  @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"resident_health_notes\")\n}\n\n/// 입소자 투약 정보\nmodel ResidentMedication {\n  /// 투약 ID (Primary Key)\n  id           BigInt    @id @default(autoincrement())\n  /// 입소자 ID (외래키)\n  residentId   BigInt    @map(\"resident_id\")\n  /// 처방의\n  prescribedBy String?   @map(\"prescribed_by\")\n  /// 약물명\n  drugName     String    @map(\"drug_name\")\n  /// 용량\n  dosage       String\n  /// 복용 일정\n  schedule     String?\n  /// 투약 시작일\n  startDate    DateTime  @map(\"start_date\") @db.Date\n  /// 투약 종료일\n  endDate      DateTime? @map(\"end_date\") @db.Date\n  /// 비고\n  notes        String?\n  /// 생성일시\n  createdAt    DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt    DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  resident     Resident  @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"resident_medications\")\n}\n\n/// 입소자 활력징후 (바이탈 사인)\nmodel ResidentVital {\n  /// 활력징후 ID (Primary Key)\n  id              BigInt    @id @default(autoincrement())\n  /// 입소자 ID (외래키)\n  residentId      BigInt    @map(\"resident_id\")\n  /// 기록자 ID (외래키)\n  recordedBy      BigInt?   @map(\"recorded_by\")\n  /// 측정일시\n  measuredAt      DateTime  @default(now()) @map(\"measured_at\") @db.Timestamptz(6)\n  /// 수축기 혈압 (mmHg)\n  systolicBp      Int?      @map(\"systolic_bp\")\n  /// 이완기 혈압 (mmHg)\n  diastolicBp     Int?      @map(\"diastolic_bp\")\n  /// 심박수 (bpm)\n  heartRate       Int?      @map(\"heart_rate\")\n  /// 체온 (°C)\n  temperature     Decimal?  @db.Decimal(4, 1)\n  /// 호흡수 (회/분)\n  respiratoryRate Int?      @map(\"respiratory_rate\")\n  /// 산소포화도 (%)\n  spo2            Int?\n  /// 비고\n  notes           String?\n  recorder        Employee? @relation(\"VitalRecorder\", fields: [recordedBy], references: [id], onUpdate: NoAction)\n  resident        Resident  @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([residentId, measuredAt(sort: Desc)], map: \"idx_resident_vitals_resident_time\")\n  @@map(\"resident_vitals\")\n}\n\n/// 웹사이트 설정\nmodel WebsiteSetting {\n  /// 설정 ID (Primary Key)\n  id          BigInt    @id @default(autoincrement())\n  /// 설정 카테고리 (GENERAL, SEO, CONTACT 등)\n  category    String\n  /// 설정 키\n  key         String\n  /// 설정 값 (JSON)\n  value       Json      @default(\"{}\")\n  /// 설명\n  description String?\n  /// 활성화 여부\n  isActive    Boolean   @default(true) @map(\"is_active\")\n  /// 수정자 ID (외래키)\n  updatedBy   BigInt?   @map(\"updated_by\")\n  /// 생성일시\n  createdAt   DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  updater     Employee? @relation(\"SettingUpdater\", fields: [updatedBy], references: [id], onUpdate: NoAction)\n\n  @@unique([category, key], map: \"website_settings_uniq\")\n  @@index([category, isActive], map: \"idx_website_settings_category\")\n  @@index([category, key], map: \"idx_website_settings_category_key\")\n  @@map(\"website_settings\")\n}\n\n/// 프로그램 참석 기록\nmodel ProgramAttendance {\n  /// 참석 ID (Primary Key)\n  id         BigInt          @id @default(autoincrement())\n  /// 일정 ID (외래키)\n  scheduleId BigInt          @map(\"schedule_id\")\n  /// 입소자 ID (외래키)\n  residentId BigInt?         @map(\"resident_id\")\n  /// 직원 ID (외래키)\n  employeeId BigInt?         @map(\"employee_id\")\n  /// 역할 (PARTICIPANT, FACILITATOR 등)\n  role       String          @default(\"PARTICIPANT\")\n  /// 참석 여부\n  attended   Boolean         @default(false)\n  /// 체크인 일시\n  checkedAt  DateTime?       @map(\"checked_at\") @db.Timestamptz(6)\n  /// 비고\n  notes      String?\n  /// 생성일시\n  createdAt  DateTime        @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  employee   Employee?       @relation(fields: [employeeId], references: [id], onUpdate: NoAction)\n  resident   Resident?       @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  schedule   ProgramSchedule @relation(fields: [scheduleId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@unique([scheduleId, residentId], map: \"program_attendance_uniq\")\n  @@map(\"program_attendance\")\n}\n\n/// 케어 플랜 (돌봄 계획)\nmodel CarePlan {\n  /// 케어 플랜 ID (Primary Key)\n  id          BigInt         @id @default(autoincrement())\n  /// 입소자 ID (외래키)\n  residentId  BigInt         @map(\"resident_id\")\n  /// 생성자 ID (외래키)\n  createdBy   BigInt?        @map(\"created_by\")\n  /// 케어 플랜 제목\n  title       String\n  /// 목표 요약\n  goalSummary String?        @map(\"goal_summary\")\n  /// 시작일\n  startDate   DateTime       @map(\"start_date\") @db.Date\n  /// 종료일\n  endDate     DateTime?      @map(\"end_date\") @db.Date\n  /// 상태 (ACTIVE, COMPLETED, CANCELLED)\n  status      String         @default(\"ACTIVE\")\n  /// 생성일시\n  createdAt   DateTime       @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime       @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  items       CarePlanItem[]\n  creator     Employee?      @relation(\"CarePlanCreator\", fields: [createdBy], references: [id], onUpdate: NoAction)\n  resident    Resident       @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"care_plans\")\n}\n\n/// 케어 플랜 세부 항목\nmodel CarePlanItem {\n  /// 항목 ID (Primary Key)\n  id          BigInt   @id @default(autoincrement())\n  /// 케어 플랜 ID (외래키)\n  carePlanId  BigInt   @map(\"care_plan_id\")\n  /// 순서 번호\n  sequenceNo  Int      @map(\"sequence_no\")\n  /// 항목 설명\n  description String\n  /// 실시 빈도\n  frequency   String?\n  /// 비고\n  notes       String?\n  /// 생성일시\n  createdAt   DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  carePlan    CarePlan @relation(fields: [carePlanId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@unique([carePlanId, sequenceNo], map: \"care_plan_items_seq_uniq\")\n  @@map(\"care_plan_items\")\n}\n\n/// 상담 기록\nmodel ConsultationRecord {\n  /// 상담 ID (Primary Key)\n  id           BigInt             @id @default(autoincrement())\n  /// 입소자 ID (외래키)\n  residentId   BigInt             @map(\"resident_id\")\n  /// 상담자 ID (외래키)\n  counselorId  BigInt?            @map(\"counselor_id\")\n  /// 상담일시\n  consultedAt  DateTime           @default(now()) @map(\"consulted_at\") @db.Timestamptz(6)\n  /// 상담 유형 (GENERAL, FAMILY, MEDICAL 등)\n  type         String             @default(\"GENERAL\")\n  /// 상담 채널 (전화, 대면, 온라인 등)\n  channel      String?\n  /// 상담 요약\n  summary      String\n  /// 상담 상세 내용\n  details      String?\n  /// 후속 조치 예정일\n  followUpDate DateTime?          @map(\"follow_up_date\") @db.Date\n  /// 생성일시\n  createdAt    DateTime           @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  files        ConsultationFile[]\n  counselor    Employee?          @relation(\"ConsultationCounselor\", fields: [counselorId], references: [id], onUpdate: NoAction)\n  resident     Resident           @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"consultation_records\")\n}\n\n/// 상담 첨부 파일\nmodel ConsultationFile {\n  /// 연결 ID (Primary Key)\n  id             BigInt             @id @default(autoincrement())\n  /// 상담 ID (외래키)\n  consultationId BigInt             @map(\"consultation_id\")\n  /// 파일 ID (외래키)\n  fileId         BigInt             @map(\"file_id\")\n  /// 생성일시\n  createdAt      DateTime           @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  consultation   ConsultationRecord @relation(fields: [consultationId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  file           FileStorage        @relation(\"ConsultationFiles\", fields: [fileId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"consultation_files\")\n}\n\n/// 사건/사고 기록\nmodel Incident {\n  /// 사건 ID (Primary Key)\n  id          BigInt         @id @default(autoincrement())\n  /// 입소자 ID (외래키)\n  residentId  BigInt?        @map(\"resident_id\")\n  /// 보고자 ID (외래키)\n  reportedBy  BigInt?        @map(\"reported_by\")\n  /// 발생일시\n  occurredAt  DateTime       @map(\"occurred_at\") @db.Timestamptz(6)\n  /// 심각도 (LOW, MEDIUM, HIGH, CRITICAL)\n  severity    String\n  /// 사건 제목\n  title       String\n  /// 사건 상세 설명\n  description String\n  /// 발생 장소\n  location    String?\n  /// 처리 상태 (OPEN, IN_PROGRESS, CLOSED)\n  status      String         @default(\"OPEN\")\n  /// 조치 사항\n  actionTaken String?        @map(\"action_taken\")\n  /// 생성일시\n  createdAt   DateTime       @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime       @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  files       IncidentFile[]\n  reporter    Employee?      @relation(\"IncidentReporter\", fields: [reportedBy], references: [id], onUpdate: NoAction)\n  resident    Resident?      @relation(fields: [residentId], references: [id], onUpdate: NoAction)\n\n  @@map(\"incidents\")\n}\n\n/// 사건 첨부 파일\nmodel IncidentFile {\n  /// 연결 ID (Primary Key)\n  id         BigInt      @id @default(autoincrement())\n  /// 사건 ID (외래키)\n  incidentId BigInt      @map(\"incident_id\")\n  /// 파일 ID (외래키)\n  fileId     BigInt      @map(\"file_id\")\n  /// 생성일시\n  createdAt  DateTime    @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  file       FileStorage @relation(\"IncidentFiles\", fields: [fileId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  incident   Incident    @relation(fields: [incidentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"incident_files\")\n}\n\n/// 케어 업무/태스크\nmodel CareTask {\n  /// 업무 ID (Primary Key)\n  id          BigInt    @id @default(autoincrement())\n  /// 입소자 ID (외래키)\n  residentId  BigInt    @map(\"resident_id\")\n  /// 배정자 ID (외래키)\n  assignedTo  BigInt?   @map(\"assigned_to\")\n  /// 마감일시\n  dueAt       DateTime? @map(\"due_at\") @db.Timestamptz(6)\n  /// 업무 제목\n  title       String\n  /// 업무 설명\n  description String?\n  /// 상태 (PENDING, IN_PROGRESS, COMPLETED, CANCELLED)\n  status      String    @default(\"PENDING\")\n  /// 우선순위 (LOW, NORMAL, HIGH, URGENT)\n  priority    String    @default(\"NORMAL\")\n  /// 생성일시\n  createdAt   DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  assignee    Employee? @relation(\"CareTaskAssignee\", fields: [assignedTo], references: [id], onUpdate: NoAction)\n  resident    Resident  @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"care_tasks\")\n}\n\n/// 일일 케어 기록 (간호, 체중, 구강, 응급, 배설)\nmodel DailyCareRecord {\n  /// 기록 ID (Primary Key)\n  id          BigInt   @id @default(autoincrement())\n  /// 입소자 ID (외래키)\n  residentId  BigInt   @map(\"resident_id\")\n  /// 기록 날짜\n  date        DateTime @db.Date\n  /// 간호 기록 (JSON)\n  nursing     Json?\n  /// 체중 기록 (JSON)\n  weight      Json?\n  /// 구강 기록 (JSON)\n  oral        Json?\n  /// 응급 기록 (JSON)\n  emergency   Json?\n  /// 배설 기록 (JSON)\n  elimination Json?\n  /// 생성일시\n  createdAt   DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  resident    Resident @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@unique([residentId, date], map: \"daily_care_records_uniq\")\n  @@map(\"daily_care_records\")\n}\n\n/// 직원 출퇴근 기록\nmodel AttendanceRecord {\n  /// 출근 기록 ID (Primary Key)\n  id         BigInt    @id @default(autoincrement())\n  /// 직원 ID (외래키)\n  employeeId BigInt    @map(\"employee_id\")\n  /// 근무 날짜\n  workDate   DateTime  @map(\"work_date\") @db.Date\n  /// 출근 시각\n  checkInAt  DateTime? @map(\"check_in_at\") @db.Timestamptz(6)\n  /// 퇴근 시각\n  checkOutAt DateTime? @map(\"check_out_at\") @db.Timestamptz(6)\n  /// 출근 상태 (PRESENT, ABSENT, LATE, EARLY_LEAVE 등)\n  status     String    @default(\"PRESENT\")\n  /// 비고\n  notes      String?\n  /// 생성일시\n  createdAt  DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt  DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  employee   Employee  @relation(fields: [employeeId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@unique([employeeId, workDate], map: \"attendance_records_uniq\")\n  @@index([status], map: \"idx_attendance_status\")\n  @@index([workDate(sort: Desc)], map: \"idx_attendance_work_date\")\n  @@map(\"attendance_records\")\n}\n\n/// 근무 시간 템플릿\nmodel ShiftTemplate {\n  /// 템플릿 ID (Primary Key)\n  id          BigInt            @id @default(autoincrement())\n  /// 템플릿 코드 (고유값)\n  code        String            @unique\n  /// 템플릿명 (예: 주간, 야간, 교대)\n  name        String\n  /// 근무 시작 시각\n  startTime   DateTime          @map(\"start_time\") @db.Time(6)\n  /// 근무 종료 시각\n  endTime     DateTime          @map(\"end_time\") @db.Time(6)\n  /// 생성일시\n  createdAt   DateTime          @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime          @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  assignments ShiftAssignment[]\n\n  @@map(\"shift_templates\")\n}\n\n/// 근무표 배정\nmodel ShiftAssignment {\n  /// 배정 ID (Primary Key)\n  id              BigInt         @id @default(autoincrement())\n  /// 직원 ID (외래키)\n  employeeId      BigInt         @map(\"employee_id\")\n  /// 근무 날짜\n  workDate        DateTime       @map(\"work_date\") @db.Date\n  /// 근무 템플릿 ID (외래키)\n  shiftTemplateId BigInt?        @map(\"shift_template_id\")\n  /// 근무 시작일시\n  startsAt        DateTime       @map(\"starts_at\") @db.Timestamptz(6)\n  /// 근무 종료일시\n  endsAt          DateTime       @map(\"ends_at\") @db.Timestamptz(6)\n  /// 생성일시\n  createdAt       DateTime       @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt       DateTime       @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  employee        Employee       @relation(fields: [employeeId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  shiftTemplate   ShiftTemplate? @relation(fields: [shiftTemplateId], references: [id], onUpdate: NoAction)\n\n  @@unique([employeeId, workDate], map: \"shift_assignments_uniq\")\n  @@index([workDate(sort: Desc)], map: \"idx_shift_assignments_date\")\n  @@index([employeeId, workDate], map: \"idx_shift_assignments_employee_date\")\n  @@map(\"shift_assignments\")\n}\n\n/// 휴가 신청\nmodel LeaveRequest {\n  /// 휴가 신청 ID (Primary Key)\n  id          BigInt          @id @default(autoincrement())\n  /// 직원 ID (외래키)\n  employeeId  BigInt          @map(\"employee_id\")\n  /// 신청일시\n  requestedAt DateTime        @default(now()) @map(\"requested_at\") @db.Timestamptz(6)\n  /// 휴가 시작일\n  startDate   DateTime        @map(\"start_date\") @db.Date\n  /// 휴가 종료일\n  endDate     DateTime        @map(\"end_date\") @db.Date\n  /// 휴가 유형 (연차, 반차, 병가, 경조사 등)\n  type        String\n  /// 사유\n  reason      String?\n  /// 승인 상태 (PENDING, APPROVED, REJECTED)\n  status      String          @default(\"PENDING\")\n  /// 생성일시\n  createdAt   DateTime        @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime        @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  approvals   LeaveApproval[]\n  employee    Employee        @relation(fields: [employeeId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"leave_requests\")\n}\n\n/// 휴가 승인 내역\nmodel LeaveApproval {\n  /// 승인 내역 ID (Primary Key)\n  id             BigInt       @id @default(autoincrement())\n  /// 휴가 신청 ID (외래키)\n  leaveRequestId BigInt       @map(\"leave_request_id\")\n  /// 승인자 ID (외래키)\n  approvedBy     BigInt?      @map(\"approved_by\")\n  /// 승인일시\n  approvedAt     DateTime?    @map(\"approved_at\") @db.Timestamptz(6)\n  /// 승인 결정 (APPROVED, REJECTED)\n  decision       String\n  /// 승인 의견\n  comment        String?\n  /// 생성일시\n  createdAt      DateTime     @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  approver       Employee?    @relation(fields: [approvedBy], references: [id], onUpdate: NoAction)\n  leaveRequest   LeaveRequest @relation(fields: [leaveRequestId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"leave_approvals\")\n}\n\n/// 계정 과목 분류\nmodel AccountCategory {\n  /// 분류 ID (Primary Key)\n  id        BigInt    @id @default(autoincrement())\n  /// 분류 코드 (고유값)\n  code      String    @unique\n  /// 분류명\n  name      String\n  /// 종류 (자산, 부채, 자본, 수익, 비용)\n  kind      String\n  /// 생성일시\n  createdAt DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  accounts  Account[]\n\n  @@map(\"account_categories\")\n}\n\n/// 계정 과목\nmodel Account {\n  /// 계정 과목 ID (Primary Key)\n  id          BigInt            @id @default(autoincrement())\n  /// 분류 ID (외래키)\n  categoryId  BigInt?           @map(\"category_id\")\n  /// 계정 과목 코드 (고유값)\n  code        String            @unique\n  /// 계정 과목명\n  name        String\n  /// 설명\n  description String?\n  /// 활성화 여부\n  isActive    Boolean           @default(true) @map(\"is_active\")\n  /// 생성일시\n  createdAt   DateTime          @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime          @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  category    AccountCategory?  @relation(fields: [categoryId], references: [id], onUpdate: NoAction)\n  items       TransactionItem[]\n\n  @@map(\"accounts\")\n}\n\n/// 거래처 (공급업체)\nmodel Supplier {\n  /// 거래처 ID (Primary Key)\n  id                    BigInt                 @id @default(autoincrement())\n  /// 거래처명\n  name                  String\n  /// 사업자 번호\n  businessNo            String?                @map(\"business_no\")\n  /// 전화번호\n  phoneNumber           String?                @map(\"phone_number\")\n  /// 이메일\n  email                 String?                @db.Citext\n  /// 주소\n  address               String?\n  /// 메모\n  memo                  String?\n  /// 생성일시\n  createdAt             DateTime               @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt             DateTime               @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  inventoryTransactions InventoryTransaction[]\n  transactions          Transaction[]\n\n  @@map(\"suppliers\")\n}\n\n/// 회계 거래 (전표)\nmodel Transaction {\n  /// 거래 ID (Primary Key)\n  id          BigInt            @id @default(autoincrement())\n  /// 거래일\n  txnDate     DateTime          @map(\"txn_date\") @db.Date\n  /// 적요 (거래 설명)\n  description String?\n  /// 참조 번호 (증빙 번호 등)\n  referenceNo String?           @map(\"reference_no\")\n  /// 거래처 ID (외래키)\n  supplierId  BigInt?           @map(\"supplier_id\")\n  /// 생성자 ID (외래키)\n  createdBy   BigInt?           @map(\"created_by\")\n  /// 총 금액\n  totalAmount Decimal           @default(0) @map(\"total_amount\") @db.Decimal(14, 2)\n  /// 통화 (KRW, USD 등)\n  currency    String            @default(\"KRW\")\n  /// 생성일시\n  createdAt   DateTime          @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime          @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  items       TransactionItem[]\n  creator     Employee?         @relation(fields: [createdBy], references: [id], onUpdate: NoAction)\n  supplier    Supplier?         @relation(fields: [supplierId], references: [id], onUpdate: NoAction)\n\n  @@index([txnDate(sort: Desc)], map: \"idx_transactions_date\")\n  @@index([supplierId], map: \"idx_transactions_supplier\")\n  @@map(\"transactions\")\n}\n\n/// 회계 거래 항목 (분개)\nmodel TransactionItem {\n  /// 항목 ID (Primary Key)\n  id            BigInt      @id @default(autoincrement())\n  /// 거래 ID (외래키)\n  transactionId BigInt      @map(\"transaction_id\")\n  /// 계정 과목 ID (외래키)\n  accountId     BigInt      @map(\"account_id\")\n  /// 라인 번호\n  lineNo        Int         @map(\"line_no\")\n  /// 적요\n  description   String?\n  /// 차변 금액\n  debitAmount   Decimal     @default(0) @map(\"debit_amount\") @db.Decimal(14, 2)\n  /// 대변 금액\n  creditAmount  Decimal     @default(0) @map(\"credit_amount\") @db.Decimal(14, 2)\n  /// 생성일시\n  createdAt     DateTime    @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  account       Account     @relation(fields: [accountId], references: [id], onUpdate: NoAction)\n  transaction   Transaction @relation(fields: [transactionId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@unique([transactionId, lineNo], map: \"transaction_items_line_uniq\")\n  @@index([accountId], map: \"idx_transaction_items_account\")\n  @@map(\"transaction_items\")\n}\n\n/// 급여 지급 내역\nmodel PayrollRecord {\n  /// 급여 내역 ID (Primary Key)\n  id             BigInt        @id @default(autoincrement())\n  /// 직원 ID (외래키)\n  employeeId     BigInt        @map(\"employee_id\")\n  /// 급여 기간 시작일\n  periodStart    DateTime      @map(\"period_start\") @db.Date\n  /// 급여 기간 종료일\n  periodEnd      DateTime      @map(\"period_end\") @db.Date\n  /// 기본급\n  baseSalary     Decimal       @default(0) @map(\"base_salary\") @db.Decimal(14, 2)\n  /// 수당 합계\n  totalAllowance Decimal       @default(0) @map(\"total_allowance\") @db.Decimal(14, 2)\n  /// 공제 합계\n  totalDeduction Decimal       @default(0) @map(\"total_deduction\") @db.Decimal(14, 2)\n  /// 실 수령액\n  netPay         Decimal       @default(0) @map(\"net_pay\") @db.Decimal(14, 2)\n  /// 지급일시\n  paidAt         DateTime?     @map(\"paid_at\") @db.Timestamptz(6)\n  /// 상태 (PENDING, PAID)\n  status         String        @default(\"PENDING\")\n  /// 생성일시\n  createdAt      DateTime      @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt      DateTime      @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  items          PayrollItem[]\n  employee       Employee      @relation(fields: [employeeId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([periodStart, periodEnd], map: \"idx_payroll_records_period\")\n  @@index([status], map: \"idx_payroll_records_status\")\n  @@map(\"payroll_records\")\n}\n\n/// 급여 세부 항목 (수당, 공제 등)\nmodel PayrollItem {\n  /// 항목 ID (Primary Key)\n  id        BigInt        @id @default(autoincrement())\n  /// 급여 내역 ID (외래키)\n  payrollId BigInt        @map(\"payroll_id\")\n  /// 항목 종류 (ALLOWANCE, DEDUCTION)\n  kind      String\n  /// 항목명 (야간수당, 국민연금 등)\n  name      String\n  /// 금액\n  amount    Decimal       @db.Decimal(14, 2)\n  /// 생성일시\n  createdAt DateTime      @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  payroll   PayrollRecord @relation(fields: [payrollId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@map(\"payroll_items\")\n}\n\n/// 청구서 헤더\nmodel InvoiceHeader {\n  /// 청구서 ID (Primary Key)\n  id          BigInt        @id @default(autoincrement())\n  /// 청구서 번호 (고유값)\n  invoiceNo   String        @unique @map(\"invoice_no\")\n  /// 입소자 ID (외래키)\n  residentId  BigInt?       @map(\"resident_id\")\n  /// 발행일\n  issueDate   DateTime      @map(\"issue_date\") @db.Date\n  /// 납기일\n  dueDate     DateTime?     @map(\"due_date\") @db.Date\n  /// 총 금액\n  totalAmount Decimal       @default(0) @map(\"total_amount\") @db.Decimal(14, 2)\n  /// 상태 (DRAFT, ISSUED, PAID, CANCELLED)\n  status      String        @default(\"DRAFT\")\n  /// 생성일시\n  createdAt   DateTime      @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt   DateTime      @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  resident    Resident?     @relation(fields: [residentId], references: [id], onUpdate: NoAction)\n  items       InvoiceItem[]\n\n  @@map(\"invoice_headers\")\n}\n\n/// 청구서 항목\nmodel InvoiceItem {\n  /// 항목 ID (Primary Key)\n  id          BigInt        @id @default(autoincrement())\n  /// 청구서 ID (외래키)\n  invoiceId   BigInt        @map(\"invoice_id\")\n  /// 라인 번호\n  lineNo      Int           @map(\"line_no\")\n  /// 항목 설명\n  description String\n  /// 수량\n  quantity    Decimal       @default(1) @db.Decimal(10, 2)\n  /// 단가\n  unitPrice   Decimal       @default(0) @map(\"unit_price\") @db.Decimal(14, 2)\n  /// 금액\n  amount      Decimal       @default(0) @db.Decimal(14, 2)\n  /// 생성일시\n  createdAt   DateTime      @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  invoice     InvoiceHeader @relation(fields: [invoiceId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@unique([invoiceId, lineNo], map: \"invoice_items_line_uniq\")\n  @@map(\"invoice_items\")\n}\n\n/// 보험 청구 (장기요양보험 등)\nmodel InsuranceClaim {\n  /// 청구 ID (Primary Key)\n  id             BigInt                  @id @default(autoincrement())\n  /// 청구 번호 (고유값)\n  claimNo        String                  @unique @map(\"claim_no\")\n  /// 입소자 ID (외래키)\n  residentId     BigInt                  @map(\"resident_id\")\n  /// 청구 월\n  claimMonth     DateTime                @map(\"claim_month\") @db.Date\n  /// 청구 유형 (요양급여, 건강보험 등)\n  claimType      String                  @map(\"claim_type\")\n  /// 청구 총액\n  totalAmount    Decimal                 @default(0) @map(\"total_amount\") @db.Decimal(14, 2)\n  /// 인정 금액\n  approvedAmount Decimal?                @map(\"approved_amount\") @db.Decimal(14, 2)\n  /// 제출일시\n  submittedAt    DateTime?               @map(\"submitted_at\") @db.Timestamptz(6)\n  /// 승인일시\n  approvedAt     DateTime?               @map(\"approved_at\") @db.Timestamptz(6)\n  /// 지급일시\n  paidAt         DateTime?               @map(\"paid_at\") @db.Timestamptz(6)\n  /// 상태 (DRAFT, SUBMITTED, APPROVED, REJECTED, PAID)\n  status         String                  @default(\"DRAFT\")\n  /// 거부 사유\n  rejectReason   String?                 @map(\"reject_reason\")\n  /// 비고\n  notes          String?\n  /// 생성자 ID (외래키)\n  createdBy      BigInt?                 @map(\"created_by\")\n  /// 생성일시\n  createdAt      DateTime                @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt      DateTime                @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  history        InsuranceClaimHistory[]\n  items          InsuranceClaimItem[]\n  creator        Employee?               @relation(fields: [createdBy], references: [id], onUpdate: NoAction)\n  resident       Resident                @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([claimNo], map: \"idx_insurance_claims_claim_no\")\n  @@index([residentId], map: \"idx_insurance_claims_resident\")\n  @@index([residentId, claimMonth(sort: Desc)], map: \"idx_insurance_claims_resident_month\")\n  @@index([status, claimMonth(sort: Desc)], map: \"idx_insurance_claims_status\")\n  @@map(\"insurance_claims\")\n}\n\n/// 보험 청구 항목\nmodel InsuranceClaimItem {\n  /// 항목 ID (Primary Key)\n  id          BigInt         @id @default(autoincrement())\n  /// 청구 ID (외래키)\n  claimId     BigInt         @map(\"claim_id\")\n  /// 서비스 일자\n  serviceDate DateTime       @map(\"service_date\") @db.Date\n  /// 서비스 코드\n  serviceCode String         @map(\"service_code\")\n  /// 서비스명\n  serviceName String         @map(\"service_name\")\n  /// 수량\n  quantity    Decimal        @default(1) @db.Decimal(10, 2)\n  /// 단가\n  unitPrice   Decimal        @default(0) @map(\"unit_price\") @db.Decimal(14, 2)\n  /// 금액\n  amount      Decimal        @default(0) @db.Decimal(14, 2)\n  /// 본인 부담금\n  copayAmount Decimal        @default(0) @map(\"copay_amount\") @db.Decimal(14, 2)\n  /// 비고\n  notes       String?\n  /// 생성일시\n  createdAt   DateTime       @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  claim       InsuranceClaim @relation(fields: [claimId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([claimId, serviceDate], map: \"idx_insurance_claim_items_claim\")\n  @@map(\"insurance_claim_items\")\n}\n\n/// 보험 청구 상태 변경 이력\nmodel InsuranceClaimHistory {\n  /// 이력 ID (Primary Key)\n  id        BigInt         @id @default(autoincrement())\n  /// 청구 ID (외래키)\n  claimId   BigInt         @map(\"claim_id\")\n  /// 변경된 상태\n  status    String\n  /// 변경자 ID (외래키)\n  changedBy BigInt?        @map(\"changed_by\")\n  /// 변경 의견\n  comment   String?\n  /// 생성일시\n  createdAt DateTime       @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  changer   Employee?      @relation(fields: [changedBy], references: [id], onUpdate: NoAction)\n  claim     InsuranceClaim @relation(fields: [claimId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([claimId, createdAt(sort: Desc)], map: \"idx_insurance_claim_history_claim\")\n  @@map(\"insurance_claim_history\")\n}\n\n/// 재고 품목\nmodel InventoryItem {\n  /// 품목 ID (Primary Key)\n  id              BigInt                 @id @default(autoincrement())\n  /// 품목 코드 (고유값)\n  code            String                 @unique\n  /// 품목명\n  name            String\n  /// 카테고리 (의약품, 소모품, 식자재 등)\n  category        String\n  /// 단위 (개, 박스, kg 등)\n  unit            String\n  /// 현재 재고량\n  currentStock    Decimal                @default(0) @map(\"current_stock\") @db.Decimal(10, 2)\n  /// 최소 재고량\n  minStock        Decimal?               @map(\"min_stock\") @db.Decimal(10, 2)\n  /// 최대 재고량\n  maxStock        Decimal?               @map(\"max_stock\") @db.Decimal(10, 2)\n  /// 단가\n  unitPrice       Decimal?               @map(\"unit_price\") @db.Decimal(14, 2)\n  /// 보관 위치\n  storageLocation String?                @map(\"storage_location\")\n  /// 활성화 여부\n  isActive        Boolean                @default(true) @map(\"is_active\")\n  /// 생성일시\n  createdAt       DateTime               @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt       DateTime               @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  transactions    InventoryTransaction[]\n\n  @@index([isActive], map: \"idx_inventory_items_active\")\n  @@index([category, isActive], map: \"idx_inventory_items_category\")\n  @@map(\"inventory_items\")\n}\n\n/// 재고 거래 내역 (입고, 출고, 조정)\nmodel InventoryTransaction {\n  /// 거래 ID (Primary Key)\n  id          BigInt        @id @default(autoincrement())\n  /// 품목 ID (외래키)\n  itemId      BigInt        @map(\"item_id\")\n  /// 거래일\n  txnDate     DateTime      @map(\"txn_date\") @db.Date\n  /// 거래 유형 (IN, OUT, ADJUST)\n  txnType     String        @map(\"txn_type\")\n  /// 수량 (입고는 +, 출고는 -)\n  quantity    Decimal       @db.Decimal(10, 2)\n  /// 단가\n  unitPrice   Decimal?      @map(\"unit_price\") @db.Decimal(14, 2)\n  /// 총 금액\n  totalAmount Decimal?      @map(\"total_amount\") @db.Decimal(14, 2)\n  /// 거래처 ID (외래키)\n  supplierId  BigInt?       @map(\"supplier_id\")\n  /// 참조 번호\n  referenceNo String?       @map(\"reference_no\")\n  /// 비고\n  notes       String?\n  /// 생성자 ID (외래키)\n  createdBy   BigInt?       @map(\"created_by\")\n  /// 생성일시\n  createdAt   DateTime      @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  creator     Employee?     @relation(fields: [createdBy], references: [id], onUpdate: NoAction)\n  item        InventoryItem @relation(fields: [itemId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  supplier    Supplier?     @relation(fields: [supplierId], references: [id], onUpdate: NoAction)\n\n  @@index([txnDate(sort: Desc)], map: \"idx_inventory_transactions_date\")\n  @@index([itemId, txnDate(sort: Desc)], map: \"idx_inventory_transactions_item_date\")\n  @@map(\"inventory_transactions\")\n}\n\n/// 차량 정보\nmodel Vehicle {\n  /// 차량 ID (Primary Key)\n  id               BigInt             @id @default(autoincrement())\n  /// 차량 번호 (고유값)\n  vehicleNo        String             @unique @map(\"vehicle_no\")\n  /// 차량 종류 (승용, 승합 등)\n  vehicleType      String             @map(\"vehicle_type\")\n  /// 모델명\n  model            String?\n  /// 제조사\n  manufacturer     String?\n  /// 연식\n  year             Int?\n  /// 정원\n  capacity         Int?\n  /// 구매일\n  purchaseDate     DateTime?          @map(\"purchase_date\") @db.Date\n  /// 마지막 점검일\n  lastInspection   DateTime?          @map(\"last_inspection\") @db.Date\n  /// 보험 만료일\n  insuranceExpires DateTime?          @map(\"insurance_expires\") @db.Date\n  /// 주행거리 (km)\n  mileage          Int?\n  /// 상태 (ACTIVE, INACTIVE, MAINTENANCE)\n  status           String             @default(\"ACTIVE\")\n  /// 비고\n  notes            String?\n  /// 생성일시\n  createdAt        DateTime           @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt        DateTime           @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  requests         TransportRequest[]\n\n  @@index([vehicleNo], map: \"idx_vehicles_no\")\n  @@index([status], map: \"idx_vehicles_status\")\n  @@map(\"vehicles\")\n}\n\n/// 운송 요청 (통원, 외출 등)\nmodel TransportRequest {\n  /// 요청 ID (Primary Key)\n  id              BigInt    @id @default(autoincrement())\n  /// 입소자 ID (외래키)\n  residentId      BigInt    @map(\"resident_id\")\n  /// 차량 ID (외래키)\n  vehicleId       BigInt?   @map(\"vehicle_id\")\n  /// 운전기사 ID (외래키)\n  driverId        BigInt?   @map(\"driver_id\")\n  /// 요청 일시\n  requestDate     DateTime  @map(\"request_date\") @db.Timestamptz(6)\n  /// 출발지\n  pickupLocation  String    @map(\"pickup_location\")\n  /// 목적지\n  destination     String\n  /// 목적\n  purpose         String?\n  /// 상태 (PENDING, APPROVED, COMPLETED, CANCELLED)\n  status          String    @default(\"PENDING\")\n  /// 실제 출발 시각\n  actualDeparture DateTime? @map(\"actual_departure\") @db.Timestamptz(6)\n  /// 실제 도착 시각\n  actualArrival   DateTime? @map(\"actual_arrival\") @db.Timestamptz(6)\n  /// 비고\n  notes           String?\n  /// 생성자 ID (외래키)\n  createdBy       BigInt?   @map(\"created_by\")\n  /// 생성일시\n  createdAt       DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt       DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  creator         Employee? @relation(\"TransportCreator\", fields: [createdBy], references: [id], onUpdate: NoAction)\n  driver          Employee? @relation(\"TransportDriver\", fields: [driverId], references: [id], onUpdate: NoAction)\n  resident        Resident  @relation(fields: [residentId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  vehicle         Vehicle?  @relation(fields: [vehicleId], references: [id], onUpdate: NoAction)\n\n  @@index([requestDate(sort: Desc)], map: \"idx_transport_requests_date\")\n  @@index([residentId], map: \"idx_transport_requests_resident\")\n  @@map(\"transport_requests\")\n}\n\n/// CCTV 장비 정보\nmodel CctvDevice {\n  /// 장비 ID (Primary Key)\n  id            BigInt        @id @default(autoincrement())\n  /// 장비 번호 (고유값)\n  deviceNo      String        @unique @map(\"device_no\")\n  /// 설치 위치\n  location      String\n  /// IP 주소\n  ipAddress     String?       @map(\"ip_address\")\n  /// 모델명\n  model         String?\n  /// 설치일\n  installDate   DateTime?     @map(\"install_date\") @db.Date\n  /// 마지막 점검일\n  lastCheckDate DateTime?     @map(\"last_check_date\") @db.Date\n  /// 상태 (ACTIVE, INACTIVE, MALFUNCTION)\n  status        String        @default(\"ACTIVE\")\n  /// 비고\n  notes         String?\n  /// 생성일시\n  createdAt     DateTime      @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt     DateTime      @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  logs          CctvViewLog[]\n\n  @@index([status], map: \"idx_cctv_devices_status\")\n  @@map(\"cctv_devices\")\n}\n\n/// CCTV 조회 로그\nmodel CctvViewLog {\n  /// 로그 ID (Primary Key)\n  id         BigInt     @id @default(autoincrement())\n  /// 장비 ID (외래키)\n  deviceId   BigInt     @map(\"device_id\")\n  /// 조회자 ID (외래키)\n  viewerId   BigInt     @map(\"viewer_id\")\n  /// 조회 시작 시각\n  viewStart  DateTime   @map(\"view_start\") @db.Timestamptz(6)\n  /// 조회 종료 시각\n  viewEnd    DateTime?  @map(\"view_end\") @db.Timestamptz(6)\n  /// 조회 목적\n  purpose    String\n  /// 승인자 ID (외래키)\n  approvedBy BigInt?    @map(\"approved_by\")\n  /// 생성일시\n  createdAt  DateTime   @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  approver   Employee?  @relation(\"CctvApprover\", fields: [approvedBy], references: [id], onUpdate: NoAction)\n  device     CctvDevice @relation(fields: [deviceId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n  viewer     Employee   @relation(\"CctvViewer\", fields: [viewerId], references: [id], onDelete: Cascade, onUpdate: NoAction)\n\n  @@index([deviceId, viewStart(sort: Desc)], map: \"idx_cctv_view_logs_device_time\")\n  @@index([viewerId, viewStart(sort: Desc)], map: \"idx_cctv_view_logs_viewer\")\n  @@map(\"cctv_view_logs\")\n}\n\n/// 민원 접수 및 처리\nmodel Grievance {\n  /// 민원 ID (Primary Key)\n  id                  BigInt    @id @default(autoincrement())\n  /// 민원 번호 (고유값)\n  grievanceNo         String    @unique @map(\"grievance_no\")\n  /// 민원인 이름\n  complainantName     String    @map(\"complainant_name\")\n  /// 민원인 연락처\n  complainantPhone    String?   @map(\"complainant_phone\")\n  /// 민원인과의 관계\n  complainantRelation String?   @map(\"complainant_relation\")\n  /// 입소자 ID (외래키)\n  residentId          BigInt?   @map(\"resident_id\")\n  /// 민원 카테고리 (서비스, 시설, 직원 등)\n  category            String\n  /// 민원 제목\n  title               String\n  /// 민원 내용\n  content             String\n  /// 접수일시\n  receivedAt          DateTime  @default(now()) @map(\"received_at\") @db.Timestamptz(6)\n  /// 접수 방법 (전화, 방문, 온라인 등)\n  receivedMethod      String?   @map(\"received_method\")\n  /// 담당자 ID (외래키)\n  assignedTo          BigInt?   @map(\"assigned_to\")\n  /// 처리 상태 (RECEIVED, IN_PROGRESS, RESOLVED, CLOSED)\n  status              String    @default(\"RECEIVED\")\n  /// 답변 내용\n  response            String?\n  /// 해결일시\n  resolvedAt          DateTime? @map(\"resolved_at\") @db.Timestamptz(6)\n  /// 생성일시\n  createdAt           DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt           DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  assignee            Employee? @relation(\"GrievanceAssignee\", fields: [assignedTo], references: [id], onUpdate: NoAction)\n  resident            Resident? @relation(fields: [residentId], references: [id], onUpdate: NoAction)\n\n  @@index([residentId], map: \"idx_grievances_resident\")\n  @@index([status, receivedAt(sort: Desc)], map: \"idx_grievances_status\")\n  @@index([status, receivedAt(sort: Desc)], map: \"idx_grievances_status_received\")\n  @@map(\"grievances\")\n}\n\n/// 시설 점검 기록\nmodel FacilityInspection {\n  /// 점검 ID (Primary Key)\n  id                 BigInt    @id @default(autoincrement())\n  /// 점검일\n  inspectionDate     DateTime  @map(\"inspection_date\") @db.Date\n  /// 점검 유형 (정기, 비정기, 안전, 위생 등)\n  inspectionType     String    @map(\"inspection_type\")\n  /// 점검자 ID (외래키)\n  inspectorId        BigInt?   @map(\"inspector_id\")\n  /// 점검 장소\n  location           String?\n  /// 점검 항목 (JSON)\n  checklist          Json?\n  /// 발견 사항\n  findings           String?\n  /// 시정 조치\n  correctiveActions  String?   @map(\"corrective_actions\")\n  /// 상태 (PENDING, COMPLETED)\n  status             String    @default(\"PENDING\")\n  /// 다음 점검 예정일\n  nextInspectionDate DateTime? @map(\"next_inspection_date\") @db.Date\n  /// 생성일시\n  createdAt          DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  /// 수정일시\n  updatedAt          DateTime  @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  inspector          Employee? @relation(\"InspectionInspector\", fields: [inspectorId], references: [id], onUpdate: NoAction)\n\n  @@index([inspectionDate(sort: Desc)], map: \"idx_facility_inspections_date\")\n  @@index([status], map: \"idx_facility_inspections_status\")\n  @@index([inspectionType], map: \"idx_facility_inspections_type\")\n  @@map(\"facility_inspections\")\n}\n\n/// SMS 발송 로그\nmodel SmsSendLog {\n  /// 로그 ID (Primary Key)\n  id             BigInt    @id @default(autoincrement())\n  /// 수신자 전화번호\n  recipientPhone String    @map(\"recipient_phone\")\n  /// 수신자 이름\n  recipientName  String?   @map(\"recipient_name\")\n  /// 메시지 내용\n  message        String\n  /// 발송 유형 (SINGLE, BULK, SCHEDULED)\n  sendType       String    @map(\"send_type\")\n  /// 예약 발송 시각\n  scheduledAt    DateTime? @map(\"scheduled_at\") @db.Timestamptz(6)\n  /// 실제 발송 시각\n  sentAt         DateTime? @map(\"sent_at\") @db.Timestamptz(6)\n  /// 발송 상태 (PENDING, SUCCESS, FAILED)\n  status         String    @default(\"PENDING\")\n  /// 오류 메시지\n  errorMessage   String?   @map(\"error_message\")\n  /// SMS 건수 (장문 시 2건 이상)\n  smsCount       Int       @default(1) @map(\"sms_count\")\n  /// 발송 비용\n  cost           Decimal?  @db.Decimal(10, 2)\n  /// 결과 코드\n  resultCode     String?   @map(\"result_code\")\n  /// 발송자 ID (외래키)\n  senderId       BigInt?   @map(\"sender_id\")\n  /// 생성일시\n  createdAt      DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  sender         Employee? @relation(fields: [senderId], references: [id], onUpdate: NoAction)\n\n  @@index([recipientPhone], map: \"idx_sms_send_logs_recipient\")\n  @@index([sentAt(sort: Desc)], map: \"idx_sms_send_logs_sent\")\n  @@index([status, scheduledAt(sort: Desc)], map: \"idx_sms_send_logs_status_scheduled\")\n  @@map(\"sms_send_logs\")\n}\n\n/// 파일 저장소 (S3, 로컬 등)\nmodel FileStorage {\n  /// 파일 ID (Primary Key)\n  id                BigInt             @id @default(autoincrement())\n  /// 저장소 버킷\n  bucket            String             @default(\"default\")\n  /// 파일 경로\n  path              String\n  /// 원본 파일명\n  originalName      String?            @map(\"original_name\")\n  /// MIME 타입\n  mimeType          String?            @map(\"mime_type\")\n  /// 파일 크기 (바이트)\n  sizeBytes         BigInt?            @map(\"size_bytes\")\n  /// 체크섬 (MD5, SHA256 등)\n  checksum          String?\n  /// 업로드자 ID (외래키)\n  createdBy         BigInt?            @map(\"created_by\")\n  /// 생성일시\n  createdAt         DateTime           @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  boardFiles        BoardFile[]        @relation(\"BoardFiles\")\n  consultationFiles ConsultationFile[] @relation(\"ConsultationFiles\")\n  creator           Employee?          @relation(\"FileCreator\", fields: [createdBy], references: [id], onUpdate: NoAction)\n  galleryFiles      GalleryFile[]      @relation(\"GalleryFiles\")\n  incidentFiles     IncidentFile[]     @relation(\"IncidentFiles\")\n  noticeFiles       NoticeFile[]       @relation(\"NoticeFiles\")\n\n  @@unique([bucket, path], map: \"uq_file_storage_bucket_path\")\n  @@index([createdAt(sort: Desc)], map: \"idx_file_storage_created_at\")\n  @@index([createdBy], map: \"idx_file_storage_created_by\")\n  @@map(\"file_storage\")\n}\n\n/// ===============================\n/// 감사 로그 (Audit Log)\n/// - 시스템 내 모든 주요 변경 이력을 기록\n/// - 누가(actor) 언제 무엇을(action) 어떤 엔티티에 대해 수행했는지 추적\n/// ===============================\nmodel AuditLog {\n  /// 로그 ID (Primary Key)\n  id         BigInt    @id @default(autoincrement())\n  /// 작업을 수행한 사용자 ID (Employee.id 참조)\n  /// 시스템 작업일 경우 NULL 가능\n  actorId    BigInt?   @map(\"actor_id\")\n  /// 수행된 작업 유형\n  /// 예: CREATE, UPDATE, DELETE, LOGIN 등\n  action     String\n  /// 변경 대상 엔티티 타입 (테이블명 또는 도메인명)\n  /// 예: Employee, Reservation, Payment\n  entityType String?   @map(\"entity_type\")\n  /// 변경 대상 엔티티의 ID\n  entityId   BigInt?   @map(\"entity_id\")\n  /// 변경 내용 (이전/이후 값 등)\n  /// 구조는 서비스 로직에서 자유롭게 정의\n  changes    Json?\n  /// 요청 발생 IP 주소\n  ipAddress  String?   @map(\"ip_address\")\n  /// 사용자 브라우저 / 디바이스 정보\n  userAgent  String?   @map(\"user_agent\")\n  /// 로그 생성 시각\n  createdAt  DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  actor      Employee? @relation(\"AuditActor\", fields: [actorId], references: [id], onUpdate: NoAction)\n\n  @@index([actorId, createdAt(sort: Desc)], map: \"idx_audit_logs_actor\")\n  @@index([createdAt(sort: Desc)], map: \"idx_audit_logs_created\")\n  @@index([entityType, entityId], map: \"idx_audit_logs_entity\")\n  @@map(\"audit_logs\")\n}\n\n/// ===============================\n/// 시스템 설정 (Key-Value 기반)\n/// - 운영 중 변경 가능한 설정값 저장\n/// - 캐시 or 관리자 페이지에서 주로 사용\n/// ===============================\nmodel SystemSetting {\n  /// 설정 키 (Primary Key)\n  /// 예: \"MAX_RESERVATION_COUNT\", \"ENABLE_SMS\"\n  key         String   @id\n  /// 설정 값 (JSON 형태)\n  /// 숫자, 문자열, 객체 등 유연하게 저장 가능\n  value       Json\n  /// 설정에 대한 설명\n  description String?\n  /// 마지막 수정 시각\n  updatedAt   DateTime @default(now()) @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n\n  @@map(\"system_settings\")\n}\n\n/// ===============================\n/// 알림 발송 큐\n/// - 이메일, SMS, 푸시 알림 등 비동기 발송 관리\n/// - 실패/재시도 처리에 활용\n/// ===============================\nmodel NotificationQueue {\n  /// 알림 ID (Primary Key)\n  id           BigInt    @id @default(autoincrement())\n  /// 발송 채널\n  /// 예: EMAIL, SMS, PUSH\n  channel      String\n  /// 알림 대상 타입\n  /// 예: EMPLOYEE, USER, ADMIN\n  targetType   String    @map(\"target_type\")\n  /// 알림 대상 ID\n  targetId     BigInt?   @map(\"target_id\")\n  /// 알림 제목\n  title        String?\n  /// 알림 본문\n  body         String?\n  /// 채널별 추가 데이터\n  /// 예: 템플릿 변수, 딥링크 정보\n  payload      Json      @default(\"{}\")\n  /// 발송 예정 시각\n  scheduledAt  DateTime  @default(now()) @map(\"scheduled_at\") @db.Timestamptz(6)\n  /// 실제 발송 완료 시각\n  sentAt       DateTime? @map(\"sent_at\") @db.Timestamptz(6)\n  /// 발송 상태\n  /// PENDING, SENT, FAILED\n  status       String    @default(\"PENDING\")\n  /// 발송 실패 시 에러 메시지\n  errorMessage String?   @map(\"error_message\")\n  /// 큐에 등록된 시각\n  createdAt    DateTime  @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n\n  @@index([status, scheduledAt], map: \"idx_notification_queue_status_sched\")\n  @@map(\"notification_queue\")\n}\n"
}

